package com.vandorlabs.neoforge.storage;
import com.google.gson.*;
import java.io.*;
import java.nio.file.*;
import java.util.zip.GZIPInputStream;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
/** Actual Source inherited migration and failure quarantine; no channel service is installed. */
final class StorageModulesChecks {
 private static int checks;private static final java.util.List<String> failures=new java.util.ArrayList<>();
 private static void need(boolean yes,String why){checks++;if(!yes)failures.add(why);}
 private static NativeStorageEntity fresh(ServerLevel level,BlockPos pos){level.getChunkAt(pos);level.setBlock(pos,Blocks.AIR.defaultBlockState(),18);level.setBlock(pos,StorageHostChecks.BLOCK.defaultBlockState(),18);var owner=(NativeStorageEntity)level.getBlockEntity(pos);owner.setItem(26,new ItemStack(Items.DIAMOND,7));return owner;}
 private static int previous(CompoundTag tag,ServerLevel level){return NativeStorageInventory.read(tag.getCompound(NativeStorageEntity.PREVIOUS),level.registryAccess(),NativeStorageInventory.empty()).get(26).getCount();}
 static void run(ServerLevel level,BlockPos pos)throws Exception {JsonArray cases;try(var stream=new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.storageModulesReference"))));var reader=new InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)){cases=JsonParser.parseReader(reader).getAsJsonArray();}need(cases.size()==8,"Source module coverage");int index=0;for(var value:cases){var row=value.getAsJsonObject();var raw=TagParser.parseTag(row.get("input").getAsString());var owner=fresh(level,pos);owner.loadWithComponents(raw.copy(),level.registryAccess());var saved=owner.saveWithoutMetadata(level.registryAccess());if(row.get("supported").getAsBoolean()){need(!owner.inert()&&owner.getItem(26).getCount()==7,"supported module preserves inventory case="+index);need(saved.getCompound("ForgeData").equals(TagParser.parseTag(row.get("forge").getAsString()))&&!saved.contains("TransmitterSchema"),"actual Source module normalization case="+index);var choices=NativeStorageItemSettings.configuration(NativeStorageItemSettings.pick(StorageHostChecks.BLOCK.asItem(),owner,level.registryAccess()));need(!choices.getCompound("ForgeData").contains("VandorTransmitters")&&!choices.contains("Items"),"configured pick has neither obsolete module inventory nor27slots case="+index);var expected=TagParser.parseTag(row.get("primary").getAsString()).getList("Rows",Tag.TAG_COMPOUND);if(!expected.isEmpty())need(java.util.Arrays.equals(saved.getCompound("RedstonePrimary").getList("Rows",Tag.TAG_COMPOUND).getCompound(0).getIntArray("RedstoneChannels"),expected.getCompound(0).getIntArray("RedstoneChannels")),"Source row channels migrated case="+index);}else{need(owner.inert()&&owner.isEmpty(),"unknown/opaque module refuses case="+index);var incoming=saved.copy();incoming.remove(NativeStorageEntity.PREVIOUS);need(incoming.equals(raw),"complete original unsupported module retained case="+index);need(previous(saved,level)==7,"unsupported partial module load quarantines previous usable slots case="+index);}index++;}
  var malformed=TagParser.parseTag("{ForgeData:{VandorTransmitters:[]}}");var broken=fresh(level,pos);broken.loadWithComponents(malformed.copy(),level.registryAccess());var brokenSave=broken.saveWithoutMetadata(level.registryAccess());need(broken.inert()&&broken.isEmpty()&&previous(brokenSave,level)==7,"wrong-type module envelope refuses and quarantines prior slots");brokenSave.remove(NativeStorageEntity.PREVIOUS);need(brokenSave.equals(malformed),"wrong-type module inventory original retained");
  var owner=fresh(level,pos);var header=new CompoundTag();header.putInt(NativeStorageInventory.SCHEMA,1);header.putInt(NativeStorageInventory.DATA_VERSION,net.minecraft.SharedConstants.getCurrentVersion().getDataVersion().getVersion());owner.loadWithComponents(header.copy(),level.registryAccess());need(owner.inert()&&owner.isEmpty()&&previous(owner.saveWithoutMetadata(level.registryAccess()),level)==7,"incomplete native header retains prior usable slots");var original=owner.saveWithoutMetadata(level.registryAccess());owner.loadWithComponents(header.copy(),level.registryAccess());need(owner.inert()&&owner.saveWithoutMetadata(level.registryAccess()).equals(original)&&previous(original,level)==7,"repeated incomplete native header cannot erase private quarantine");if(!failures.isEmpty())throw new AssertionError(String.join(" | ",failures));System.out.println("[vandorlabs][storage-modules] write PASS checks="+checks+" Source8/noitemcopy/opaque/refused/incomplete-native-quarantine");
 }
 static void read(ServerLevel level,BlockPos pos){level.getChunkAt(pos);var owner=(NativeStorageEntity)level.getBlockEntity(pos);need(owner!=null&&owner.inert()&&owner.isEmpty(),"incomplete native saved recovery remains inert");need(previous(owner.saveWithoutMetadata(level.registryAccess()),level)==7,"prior slots survive module/header quarantine complete-process restart");if(!failures.isEmpty())throw new AssertionError(String.join(" | ",failures));System.out.println("[vandorlabs][storage-modules] read PASS checks="+checks);}
}
